-- 161_quantity_kind_blank_set.sql
-- SCHEMA migration, compensating 156 (committed, not edited): T-083's second repair after the adversarial pass. No data
-- rows.
--
-- 1. ONE DEFINITION OF BLANK (CLAUDE.md rule 8). 156 spelled migration 154's whitespace set plus five zero-width
--    characters of its own (dbcore.ZERO_WIDTH, now deleted), so U+00AD, U+180E, U+2063 or U+034F as a whole page and
--    U+3164 as a whole quote passed. Every warrant cell now reads dbcore.blank_chars() (Unicode categories Cc, Cf, Zs,
--    Zl, Zp and U+2800, U+3164), spelled below without U+0000 as migration 160 spells it:
--     * the URL holds no blank character anywhere;
--     * the page, the clause and the ref_id are not wholly blank and hold no blank character other than a space
--       separator (category Zs: a space inside "Annex A" is legitimate; a format or control character is not);
--     * the quote is not wholly blank.
--    Test T083-12 pins both spellings to dbcore.blank_chars(); db._kind_hidden_chars() is the second set's one home.
-- 2. TYPES. quantity_kind must be TEXT (a BLOB kind passed with foreign keys off); the check sits in the row CHECK on
--    the last cell, beside the all-or-none rule, since the kind cell itself is not rebuilt here.
-- 3. THE QUOTED WORDS ARE THE OWNER'S ANSWER now: the owner ratified on 2026-11-19 that "the absorbed grounding holds
--    the locator and the words the base cell asserts were found, as far as a base refusal reads them"
--    (`grep -n -F "OD-71: the absorbed grounding holds the locator" references/project-standards.md`). 156's header,
--    which called it the owner's open question, is committed history and stays as it is.
-- Rebuilt as 156 rebuilt them: the six cells dropped (the quote first: its CHECK names the others) and added again.
-- Correct only while no parameter carries a kind; the guard aborts the migration otherwise
-- (`select count(*) from base_parameters where quantity_kind is not null`).

CREATE TEMP TABLE _161_guard (kinded INTEGER CHECK (kinded = 0));
INSERT INTO _161_guard SELECT COUNT(*) FROM base_parameters WHERE quantity_kind IS NOT NULL;
DROP TABLE _161_guard;

